      res?.headers?.["grpc-metadata-process_id"] ??
      res?.config?.processId ??
      "";

    openModalResponse({
      title: res?.data?.message || "Network Error",
      icon: "error",
      variantCloseLabel: "primary",
      processId,
      onClose: closeModalResponse,
